def manifest(check=False):
 p=ROOT/'Docs/Second-Brain/second-brain-manifest.json';d=json.loads(p.read_text());ids={x[0] for x in NEW};d['source_registry']=[r for r in d['source_registry'] if r.get('source_id') not in ids]+[{'source_id':i,'record_path':q,'canonical_url':u,'captured':'2026-10-02','rights':r} for i,q,u,r in NEW];nids={x.note_id for x in LESSONS};d['note_registry']=[n for n in d['note_registry'] if n.get('note_id') not in nids];d['retrieval_test_set']=[q for q in d['retrieval_test_set'] if q.get('expected_note_id') not in nids]
 for x in LESSONS:d['note_registry'].append({'note_id':x.note_id,'path':f'2_Wiki/Database-Systems/{x.title}.md','status':'review','source_ids':list(x.sources),'last_verified':'2026-10-02'});d['retrieval_test_set'].extend({'query':q,'expected_note_id':x.note_id} for q in QUERIES[x.number])
 d.update({'version':'1.0.47','updated_at':'2026-10-02T23:59:00+07:00'});d['layers']['1_Nguon']['source_count']=len(d['source_registry']);d['layers']['2_Wiki']['note_count']=len(d['note_registry']);e=json.dumps(d,ensure_ascii=False,indent=2)+'\n'
 if check:return [] if p.read_text()==e else [str(p.relative_to(ROOT))]
